<template>
  <div class="source-app admin-feature-app">
    <AdminAccessGate v-if="checking || locked" :checking="checking" :authenticated="authenticated" :error="authError" title="进入热门搜索管理" @authenticated="checkStatus" />
    <template v-else>
      <aside class="console-sidebar">
        <NuxtLink to="/" class="console-brand"><span class="brand-symbol"><ConsoleIcon name="box" :size="22" /></span>PanHub <span class="brand-tag">CONSOLE</span></NuxtLink>
        <nav aria-label="后台导航">
          <NuxtLink to="/admin/monitor" class="console-nav-link"><ConsoleIcon name="activity" />运行监控</NuxtLink>
          <NuxtLink to="/admin/sources" class="console-nav-link"><ConsoleIcon name="box" />来源管理</NuxtLink>
          <NuxtLink to="/admin/proxies" class="console-nav-link"><ConsoleIcon name="globe" />代理节点</NuxtLink>
          <NuxtLink to="/admin/resources" class="console-nav-link"><ConsoleIcon name="database" />网盘资源</NuxtLink>
          <NuxtLink to="/admin/hot-searches" class="console-nav-link active"><ConsoleIcon name="search" />热门搜索</NuxtLink>
          <NuxtLink to="/admin/users" class="console-nav-link"><ConsoleIcon name="user" />用户管理</NuxtLink>
          <NuxtLink to="/admin/logs" class="console-nav-link"><ConsoleIcon name="activity" />搜索日志</NuxtLink>
          <NuxtLink to="/admin/policies" class="console-nav-link"><ConsoleIcon name="sliders" />系统设置</NuxtLink>
        </nav>
      </aside>
      <div class="console-body">
        <header class="console-topbar"><div class="breadcrumbs"><ConsoleIcon name="grid" :size="16" /><span>管理后台</span><ConsoleIcon name="chevron" :size="13" /><strong>热门搜索管理</strong></div><div class="topbar-right"><button class="session-button" type="button" @click="lock">退出后台<ConsoleIcon name="logout" :size="15" /></button></div></header>
        <main class="console-main admin-feature-main"><section class="feature-content">
          <p v-if="notice" class="feature-notice" :class="{ error: noticeError }" role="status">{{ notice }}</p>
          <section class="query-panel" aria-label="热门搜索查询与操作">
            <form class="query-toolbar" @submit.prevent="loadSearches">
              <label class="query-input"><ConsoleIcon name="search" :size="16" /><input v-model.trim="query" type="search" placeholder="搜索热门词" /></label>
              <select v-model="status" class="query-select" aria-label="热门搜索状态"><option value="">全部状态</option><option value="approved">已通过</option><option value="pending">待审核</option><option value="blocked">已屏蔽</option><option value="hidden">已隐藏</option></select>
              <select v-model="source" class="query-select" aria-label="热门搜索来源"><option value="">全部来源</option><option value="auto">自动</option><option value="manual">人工</option></select>
              <div class="query-actions"><button class="button primary" type="submit"><ConsoleIcon name="search" :size="14" />查询</button><button class="button secondary" type="button" @click="resetQuery">重置</button><button class="button secondary" type="button" :disabled="!selected.length || busy" @click="changeStatus('approved')">恢复</button><button class="button danger-button" type="button" :disabled="!selected.length || busy" @click="changeStatus('blocked')"><ConsoleIcon name="lock" :size="14" />屏蔽</button><button class="button secondary" type="button" :disabled="!selected.length || busy" @click="setPinned(true)">置顶</button><button class="button danger-button" type="button" :disabled="!selected.length || busy" @click="deleteSelected"><ConsoleIcon name="trash" :size="14" />批量删除<span v-if="selected.length" class="action-count">{{ selected.length }}</span></button><button class="button primary" type="button" @click="openHotSearch()"><ConsoleIcon name="plus" :size="14" />新增热门词</button></div>
            </form>
            <div class="query-meta">已选 {{ selected.length }} 项 · 共 {{ total }} 条</div>
          </section>
          <section class="sources-panel directory-panel table-panel" aria-label="热门搜索列表">
            <div class="table-scroll"><table class="source-table admin-data-table hot-search-table"><thead><tr><th class="checkbox-column"><input type="checkbox" :checked="allSelected" :indeterminate="someSelected" aria-label="选择当前页全部热门词" @change="toggleAll" /></th><th>排名</th><th>关键词</th><th>热度</th><th>状态</th><th>来源</th><th>更新时间</th><th>操作</th></tr></thead>
              <tbody><tr v-for="(item, index) in items" :key="item.term" :class="{ 'selected-row': selected.includes(item.term) }"><td class="checkbox-column"><input type="checkbox" :checked="selected.includes(item.term)" :aria-label="`选择 ${item.term}`" @change="toggle(item.term)" /></td><td>{{ (page - 1) * pageSize + index + 1 }}<span v-if="item.pinned" class="pin-mark">置顶</span></td><td><strong>{{ item.term }}</strong></td><td>{{ item.score }}<small v-if="item.manualWeight" class="table-muted">人工权重 {{ item.manualWeight }}</small></td><td><span :class="['status-badge', `hot-status-${item.status}`]">{{ statusLabel(item.status) }}</span></td><td>{{ item.source === 'manual' ? '人工' : '自动' }}</td><td>{{ formatTime(item.updatedAt || item.lastSearched) }}</td><td class="action-column"><div class="row-actions"><button class="row-action-button" type="button" title="编辑" :aria-label="`编辑 ${item.term}`" @click="openHotSearch(item)">编辑</button><button class="row-action-button" :class="{ 'danger-action': item.status === 'approved' }" type="button" :title="item.status === 'approved' ? '屏蔽' : '恢复'" :aria-label="`${item.status === 'approved' ? '屏蔽' : '恢复'} ${item.term}`" @click="changeOneStatus(item, item.status === 'approved' ? 'blocked' : 'approved')">{{ item.status === 'approved' ? '屏蔽' : '恢复' }}</button><button class="row-action-button danger-action" type="button" title="删除" :aria-label="`删除 ${item.term}`" @click="remove(item)">删除</button></div></td></tr><tr v-if="!loading && !items.length"><td colspan="8" class="empty-cell">暂无热门搜索数据。</td></tr><tr v-if="loading"><td colspan="8" class="empty-cell">正在加载热门搜索…</td></tr></tbody>
            </table></div><AdminPagination :page="page" :total-pages="pageCount" :total="total" :page-size="pageSize" @change="goPage" @update:page-size="changePageSize" />
          </section>
        </section></main>
      </div>
    </template>
    <div v-if="hotDialog" class="admin-modal-backdrop" @click.self="closeDialogs"><section class="admin-modal" role="dialog" aria-modal="true"><header class="admin-modal-header"><div><p class="modal-eyebrow">HOT SEARCH</p><h2>{{ editingHot ? '编辑热门词' : '新增热门词' }}</h2></div><button class="modal-close" type="button" @click="closeDialogs">×</button></header><form class="resource-form" @submit.prevent="saveHotSearch"><label>关键词<input v-model.trim="hotForm.term" required maxlength="100" placeholder="输入要展示的热门搜索词" /></label><div class="form-two-col"><label>状态<select v-model="hotForm.status"><option value="approved">已通过</option><option value="pending">待审核</option><option value="blocked">已屏蔽</option><option value="hidden">已隐藏</option></select></label><label>热度<input v-model.number="hotForm.score" type="number" min="0" max="2000000000" /></label></div><div class="form-two-col"><label>人工权重<input v-model.number="hotForm.manualWeight" type="number" min="0" max="1000000" /></label><label class="checkbox-field"><input v-model="hotForm.pinned" type="checkbox" />置顶展示</label></div><p v-if="formError" class="form-error">{{ formError }}</p><div class="modal-actions"><button class="button secondary" type="button" @click="closeDialogs">取消</button><button class="button primary" type="submit" :disabled="busy">{{ busy ? '保存中…' : '保存' }}</button></div></form></section></div>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import AdminAccessGate from "./AdminAccessGate.vue";
import AdminPagination from "./AdminPagination.vue";
import ConsoleIcon from "../sources/ConsoleIcon.vue";
import type { HotSearchItem, HotSearchStatus } from "../../server/core/services/hotSearchStore";

const items = ref<HotSearchItem[]>([]); const query = ref(""); const status = ref(""); const source = ref(""); const page = ref(1); const pageSize = ref(20); const total = ref(0); const selected = ref<string[]>([]); const loading = ref(false); const busy = ref(false); const checking = ref(true); const authenticated = ref(false); const locked = ref(true); const authError = ref(""); const notice = ref(""); const noticeError = ref(false); const formError = ref(""); const hotDialog = ref(false); const editingHot = ref(false);
const hotForm = ref({ term: "", status: "approved" as HotSearchStatus, score: 0, manualWeight: 0, pinned: false, oldTerm: "" });
const pageCount = computed(() => Math.max(1, Math.ceil(total.value / pageSize.value))); const currentKeys = computed(() => items.value.map((item) => item.term)); const allSelected = computed(() => currentKeys.value.length > 0 && currentKeys.value.every((term) => selected.value.includes(term))); const someSelected = computed(() => selected.value.some((term) => currentKeys.value.includes(term)) && !allSelected.value);
function statusLabel(value: string) { return ({ approved: "已通过", pending: "待审核", blocked: "已屏蔽", hidden: "已隐藏" } as Record<string, string>)[value] || value; } function formatTime(value: number) { return value ? new Date(value).toLocaleString("zh-CN", { hour12: false }) : "—"; } function statusOf(error: any) { return error?.statusCode || error?.response?.status || error?.status; } function apiError(error: any) { const statusCode = statusOf(error); return statusCode === 401 ? "请先登录管理员账号。" : statusCode === 403 ? "当前账号没有管理员权限。" : error?.data?.statusMessage || error?.message || "后台请求失败。"; } function show(message: string, error = false) { notice.value = message; noticeError.value = error; }
async function checkStatus() { checking.value = true; authError.value = ""; try { const session = await $fetch<any>("/api/account/session", { credentials: "include", cache: "no-store", retry: 0 }); authenticated.value = !!session.authenticated; locked.value = !(authenticated.value && session.user?.role === "admin"); if (!locked.value) await loadSearches(); } catch (error: any) { locked.value = true; authError.value = apiError(error); } finally { checking.value = false; } }
async function lock() { await $fetch("/api/account/logout", { method: "POST", credentials: "include", retry: 0 }).catch(() => {}); await navigateTo("/"); }
async function loadSearches() { loading.value = true; try { const result = await $fetch<any>("/api/admin/hot-searches", { query: { q: query.value || undefined, status: status.value || undefined, source: source.value || undefined, page: page.value, pageSize: pageSize.value }, cache: "no-store" }); const data = result?.data ?? result; items.value = data.items || []; total.value = Number(data.total || 0); selected.value = selected.value.filter((term) => currentKeys.value.includes(term)); } catch (error: any) { show(apiError(error), true); if (statusOf(error) === 401) locked.value = true; } finally { loading.value = false; } }
function resetQuery() { query.value = ""; status.value = ""; source.value = ""; page.value = 1; void loadSearches(); } function goPage(next: number) { if (next >= 1 && next <= pageCount.value && next !== page.value) { page.value = next; void loadSearches(); } } function changePageSize(size: number) { pageSize.value = size; page.value = 1; void loadSearches(); } function toggle(term: string) { selected.value = selected.value.includes(term) ? selected.value.filter((item) => item !== term) : [...selected.value, term]; } function toggleAll(event: Event) { const checked = (event.target as HTMLInputElement).checked; selected.value = checked ? [...new Set([...selected.value, ...currentKeys.value])] : selected.value.filter((term) => !currentKeys.value.includes(term)); }
async function changeStatus(next: HotSearchStatus) { if (!selected.value.length || busy.value) return; busy.value = true; try { const result = await $fetch<any>("/api/admin/hot-searches/status", { method: "POST", body: { terms: selected.value, status: next } }); show(`已更新 ${Number(result?.data?.count || 0)} 条热门词。`); selected.value = []; await loadSearches(); } catch (error: any) { show(apiError(error), true); } finally { busy.value = false; } } async function changeOneStatus(item: HotSearchItem, next: HotSearchStatus) { selected.value = [item.term]; await changeStatus(next); } async function setPinned(pinned: boolean) { if (!selected.value.length || busy.value) return; busy.value = true; try { const result = await $fetch<any>("/api/admin/hot-searches/pinned", { method: "POST", body: { terms: selected.value, pinned } }); show(`已更新 ${Number(result?.data?.count || 0)} 条热门词。`); selected.value = []; await loadSearches(); } catch (error: any) { show(apiError(error), true); } finally { busy.value = false; } }
function openHotSearch(item?: HotSearchItem) { editingHot.value = !!item; formError.value = ""; hotForm.value = item ? { term: item.term, oldTerm: item.term, status: item.status, score: item.score, manualWeight: item.manualWeight, pinned: item.pinned } : { term: "", oldTerm: "", status: "approved", score: 0, manualWeight: 0, pinned: false }; hotDialog.value = true; } function closeDialogs() { if (!busy.value) hotDialog.value = false; }
async function saveHotSearch() { busy.value = true; formError.value = ""; try { const body = { term: hotForm.value.term, status: hotForm.value.status, score: hotForm.value.score, manualWeight: hotForm.value.manualWeight, pinned: hotForm.value.pinned }; await $fetch(editingHot.value ? `/api/admin/hot-searches/${encodeURIComponent(hotForm.value.oldTerm)}` : "/api/admin/hot-searches", { method: editingHot.value ? "PUT" : "POST", body }); closeDialogs(); show(editingHot.value ? "热门词已更新。" : "热门词已添加。"); await loadSearches(); } catch (error: any) { formError.value = apiError(error); } finally { busy.value = false; } } async function remove(item: HotSearchItem) { if (busy.value || !window.confirm(`确定永久删除「${item.term}」吗？`)) return; busy.value = true; try { await $fetch(`/api/admin/hot-searches/${encodeURIComponent(item.term)}`, { method: "DELETE" }); selected.value = selected.value.filter((term) => term !== item.term); show("热门词已删除。"); await loadSearches(); } catch (error: any) { show(apiError(error), true); } finally { busy.value = false; } }
async function deleteSelected() { if (!selected.value.length || busy.value || !window.confirm("确定永久删除选中的 " + selected.value.length + " 条热门词吗？")) return; busy.value = true; try { const terms = [...selected.value]; const result = await $fetch<any>("/api/admin/hot-searches/batch-delete", { method: "POST", body: { terms } }); const count = Number(result?.data?.count || 0); selected.value = []; page.value = Math.min(page.value, Math.max(1, Math.ceil((total.value - count) / pageSize.value))); show("已删除 " + count + " 条热门词。"); await loadSearches(); } catch (error: any) { show(apiError(error), true); } finally { busy.value = false; } }
onMounted(checkStatus);
</script>
