.hot-search-table small{display:block;margin-top:4px}.pin-mark{display:inline-block;margin-left:6px;padding:2px 5px;border-radius:4px;background:#fff7ed;color:#c2410c;font-size:10px}.hot-status-approved{color:#166534;background:#dcfce7}.hot-status-pending{color:#92400e;background:#fef3c7}.hot-status-blocked{color:#991b1b;background:#fee2e2}.hot-status-hidden{color:#475569;background:#e2e8f0}.checkbox-field{display:flex;align-items:center;gap:8px;padding-top:28px}.checkbox-field input{width:auto}.table-muted{color:#718096;font-size:11px}.form-two-col{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:900px){.form-two-col{grid-template-columns:1fr}}
